import RNA, random
tu='(((.(((((((...))))..))))))'
nu=len(tu)
pairs=[]
stack=[]
for i,c in enumerate(tu):
    if c=='(': stack.append(i)
    elif c==')': pairs.append((stack.pop(),i))
unpaired=[i for i,c in enumerate(tu) if c=='.']
tf='(((.(((((((...))))..))))))...(((.(((((((...))))..))))))...(((.(((((((...))))..))))))...(((.(((((((...))))..))))))...(((.(((((((...))))..))))))...(((.(((((((...))))..))))))...(((.(((((((...))))..))))))...(((.(((((((...))))..))))))'

def unit_folds(s):
    ss,_=RNA.fold(s); return RNA.bp_distance(ss,tu)==0

def rand_unit():
    seq=['A']*nu
    for a,b in pairs:
        p=random.choice(['GC','CG','AU','UA']); seq[a]=p[0]; seq[b]=p[1]
    for i in unpaired: seq[i]=random.choice('ACGU')
    return ''.join(seq)

def local_unit(seed):
    s=seed; cs,_=RNA.fold(s); cs=RNA.bp_distance(cs,tu)
    cur=s;cur_s=cs
    for it in range(300):
        if random.random()<0.6:
            a,b=random.choice(pairs); p=random.choice(['GC','CG','AU','UA'])
            cand=list(cur); cand[a]=p[0]; cand[b]=p[1]
        else:
            i=random.choice(unpaired); cand=list(cur); cand[i]=random.choice('ACGU')
        cand=''.join(cand); csc,_=RNA.fold(cand); csc=RNA.bp_distance(csc,tu)
        if csc<=cur_s and (csc<cur_s or random.random()<0.3):
            cur=cand;cur_s=csc
    return cur,cur_s

